"""Emit SQL query fixtures generated by the actual repository compiler."""
import json
import re
from postgres_store import compile_query

docs = [
    {'id':'a','status':'open','tags':['RN','ICU'],'rate':50,'user_id':'one'},
    {'id':'b','status':None,'tags':['CNA'],'rate':20,'user_id':'two'},
    {'id':'c','rate':30},
]
cases = [
    ('equality',{'user_id':'one'},['a']),
    ('null matches missing',{'status':None},['b','c']),
    ('not equal',{'status':{'$ne':'open'}},['b','c']),
    ('scalar matches array',{'tags':'RN'},['a']),
    ('in',{'tags':{'$in':['RN','CNA']}},['a','b']),
    ('nin',{'tags':{'$nin':['RN']}},['b','c']),
    ('empty in',{'id':{'$in':[]}},[]),
    ('empty nin',{'id':{'$nin':[]}},['a','b','c']),
    ('exists',{'status':{'$exists':True}},['a','b']),
    ('or',{'$or':[{'user_id':'one'},{'rate':{'$gt':25}}]},['a','c']),
    ('regex',{'user_id':{'$regex':'ONE','$options':'i'}},['a']),
]
fixtures=[]
for name, query, expected in cases:
    sql, params=compile_query(query)
    counter=iter(range(1,len(params)+1))
    sql=re.sub(r'%s',lambda _:f'${next(counter)}',sql)
    fixtures.append({'name':name,'sql':sql,'params':[json.dumps(p.obj) if hasattr(p,'obj') else p for p in params],'docs':docs,'expected':expected})
print(json.dumps(fixtures))
